// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;

    // Minimal controller surface C actually consults on these paths.
    function paused() external view returns (bool) { return false; }
    function coordinatorFor(IProduct) external view returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return address(this); }

    function setUp() public {
        // Try every (payoffType, payoffDirection) pair until one satisfies payoffDefinition().valid().
        uint256 tMax = uint256(type(PayoffDefinitionLib.PayoffType).max);
        uint256 dMax = uint256(type(PayoffDefinitionLib.PayoffDirection).max);
        for (uint256 t = 0; t <= tMax; t++) {
            for (uint256 d = 0; d <= dMax; d++) {
                Product candidate = new Product();
                IProduct.ProductInfo memory info;
                info.name = "X";
                info.symbol = "X";
                info.payoffDefinition = PayoffDefinition(
                    PayoffDefinitionLib.PayoffType(t),
                    PayoffDefinitionLib.PayoffDirection(d),
                    bytes30(0)
                );
                info.oracle = IOracleProvider(address(new OracleStub()));
                info.maintenance = UFixed18.wrap(0);
                info.fundingFee = UFixed18.wrap(0);
                info.makerFee = UFixed18.wrap(0);
                info.takerFee = UFixed18.wrap(0);
                info.positionFee = UFixed18.wrap(0);
                info.makerLimit = UFixed18.wrap(0);
                info.utilizationCurve = JumpRateUtilizationCurve(
                    PackedFixed18.wrap(0), PackedFixed18.wrap(0),
                    PackedFixed18.wrap(0), PackedUFixed18.wrap(0)
                );
                try candidate.initialize(info) {
                    c = candidate;
                    return;
                } catch {}
            }
        }
        revert("no valid payoff definition");
    }

    function testFuzz_property(uint256 v) public {
        v = bound(v, 0, 1e24);
        vm.prank(address(this));
        c.updateMaintenance(UFixed18.wrap(v));
        assertTrue(UFixed18.unwrap(c.maintenance()) == v);
    }
}

contract OracleStub {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}
